package com.example.preview;

import org.junit.jupiter.api.Test;

import java.time.Instant;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Unit tests for the PreviewDocument value object.
 * Proves AC-1: a valid preview document can be constructed and its fields are accessible.
 */
class PreviewDocumentTest {

    @Test
    void testAC_1_previewDocumentHoldsAllRequiredFields() {
        String shortCode = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String title = "Example Domain";
        String description = "An example article about something";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        PreviewDocument doc = new PreviewDocument(shortCode, targetUrl, title, description, fetchedAt, cacheExpiresAt);

        assertThat(doc.getShortCode()).isEqualTo(shortCode);
        assertThat(doc.getTargetUrl()).isEqualTo(targetUrl);
        assertThat(doc.getTitle()).isEqualTo(title);
        assertThat(doc.getDescription()).isEqualTo(description);
        assertThat(doc.getFetchedAt()).isEqualTo(fetchedAt);
        assertThat(doc.getCacheExpiresAt()).isEqualTo(cacheExpiresAt);
    }

    @Test
    void testAC_1_previewDocumentAllowsNullTitleAndDescription() {
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        PreviewDocument doc = new PreviewDocument("aB3xQ", "https://example.com", null, null, fetchedAt, cacheExpiresAt);

        assertThat(doc.getTitle()).isNull();
        assertThat(doc.getDescription()).isNull();
        assertThat(doc.getShortCode()).isNotNull();
        assertThat(doc.getTargetUrl()).isNotNull();
        assertThat(doc.getFetchedAt()).isNotNull();
    }

    @Test
    void testAC_1_previewDocumentShortCodeIsPreservedExactly() {
        String shortCode = "aB3xQ";
        PreviewDocument doc = new PreviewDocument(shortCode, "https://example.com", "Title", "Desc",
                Instant.now().toString(), Instant.now().plusSeconds(86400).toString());

        assertThat(doc.getShortCode()).isEqualTo("aB3xQ");
    }

    @Test
    void testAC_1_previewDocumentTargetUrlIsPreservedExactly() {
        String targetUrl = "https://example.com/some/article?q=1&lang=en";
        PreviewDocument doc = new PreviewDocument("aB3xQ", targetUrl, "Title", "Desc",
                Instant.now().toString(), Instant.now().plusSeconds(86400).toString());

        assertThat(doc.getTargetUrl()).isEqualTo(targetUrl);
    }

    @Test
    void testAC_1_previewDocumentFetchedAtIsIso8601() {
        String fetchedAt = "2024-06-15T12:34:56Z";
        PreviewDocument doc = new PreviewDocument("aB3xQ", "https://example.com", "Title", "Desc",
                fetchedAt, "2024-06-16T12:34:56Z");

        assertThat(doc.getFetchedAt()).isEqualTo(fetchedAt);
        // Verify it parses as a valid Instant (ISO-8601)
        assertThat(Instant.parse(doc.getFetchedAt())).isNotNull();
    }

    @Test
    void testAC_1_previewDocumentCacheExpiresAtIsIso8601() {
        String cacheExpiresAt = "2024-06-16T12:34:56Z";
        PreviewDocument doc = new PreviewDocument("aB3xQ", "https://example.com", "Title", "Desc",
                "2024-06-15T12:34:56Z", cacheExpiresAt);

        assertThat(doc.getCacheExpiresAt()).isEqualTo(cacheExpiresAt);
        assertThat(Instant.parse(doc.getCacheExpiresAt())).isNotNull();
    }
}
