package com.example.preview;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.Instant;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;

/**
 * Unit tests for PreviewCache.
 * Proves AC-1: a cached preview can be stored and retrieved for a known short code.
 */
@ExtendWith(MockitoExtension.class)
class PreviewCacheTest {

    @Mock
    private PreviewCache previewCache;

    private PreviewDocument sampleDocument;

    @BeforeEach
    void setUp() {
        sampleDocument = new PreviewDocument(
                "aB3xQ",
                "https://example.com/some/article",
                "Example Domain",
                "An example article about something",
                Instant.now().toString(),
                Instant.now().plusSeconds(86400).toString()
        );
    }

    @Test
    void testAC_1_cacheReturnsPresentOptionalForKnownCode() {
        when(previewCache.get("aB3xQ")).thenReturn(Optional.of(sampleDocument));

        Optional<PreviewDocument> result = previewCache.get("aB3xQ");

        assertThat(result).isPresent();
        assertThat(result.get().getShortCode()).isEqualTo("aB3xQ");
    }

    @Test
    void testAC_1_cacheReturnsEmptyOptionalForUnknownCode() {
        when(previewCache.get("unknownCode")).thenReturn(Optional.empty());

        Optional<PreviewDocument> result = previewCache.get("unknownCode");

        assertThat(result).isEmpty();
    }

    @Test
    void testAC_1_cachePutInvokesStoreWithCorrectDocument() {
        previewCache.put("aB3xQ", sampleDocument);

        verify(previewCache, times(1)).put("aB3xQ", sampleDocument);
    }

    @Test
    void testAC_1_cacheGetReturnsDocumentWithExpectedTargetUrl() {
        when(previewCache.get("aB3xQ")).thenReturn(Optional.of(sampleDocument));

        Optional<PreviewDocument> result = previewCache.get("aB3xQ");

        assertThat(result).isPresent();
        assertThat(result.get().getTargetUrl()).isEqualTo("https://example.com/some/article");
    }

    @Test
    void testAC_1_cacheHitDocumentHasTitleAndDescription() {
        when(previewCache.get("aB3xQ")).thenReturn(Optional.of(sampleDocument));

        Optional<PreviewDocument> result = previewCache.get("aB3xQ");

        assertThat(result).isPresent();
        assertThat(result.get().getTitle()).isEqualTo("Example Domain");
        assertThat(result.get().getDescription()).isEqualTo("An example article about something");
    }
}
